using System.Text;using System.Text.Json;namespace QuantForge.Core;public sealed class DeviceAcceptanceEvidenceFileStore{private readonly string _path;public DeviceAcceptanceEvidenceFileStore(string path)=>_path=Path.GetFullPath(path);public void Save(DeviceAcceptanceEvidence value){DeviceAcceptanceEvidenceRules.Validate(value);Directory.CreateDirectory(Path.GetDirectoryName(_path)!);File.WriteAllText(_path,JsonSerializer.Serialize(value,new JsonSerializerOptions{WriteIndented=true}),new UTF8Encoding(false));}public DeviceAcceptanceEvidence Load(){var v=JsonSerializer.Deserialize<DeviceAcceptanceEvidence>(File.ReadAllText(_path))??throw new InvalidOperationException("Device acceptance JSON is invalid.");DeviceAcceptanceEvidenceRules.Validate(v);return v;}}
